#include "emitter.h"

#include <algorithm>
#include <fstream>
#include <sstream>
#include <stdexcept>

#include <fmt/format.h>

#include "g6/log.h"

namespace g6::recomp {
namespace {

constexpr const char* kBanner =
    "// Generated by x64recomp from a user-supplied binary. Do not edit, do not commit.\n";

void write_if_changed(const std::filesystem::path& path, const std::string& content) {
    {
        const std::ifstream in(path, std::ios::binary);
        if (in) {
            std::ostringstream existing;
            existing << in.rdbuf();
            if (existing.str() == content) {
                return;
            }
        }
    }
    std::ofstream out(path, std::ios::binary | std::ios::trunc);
    out << content;
    if (!out) {
        throw std::runtime_error(fmt::format("cannot write {}", path.string()));
    }
}

bool valid_identifier(const std::string& name) {
    return !name.empty() && std::ranges::all_of(name, [](char c) {
        return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') ||
               c == '_';
    }) && (name[0] < '0' || name[0] > '9');
}

} // namespace

EmitStats emit_module(const pe::Image& image, const DiscoveryResult& discovery,
                      const EmitOptions& options, const std::filesystem::path& out_dir) {
    const uint64_t base = options.base != 0 ? options.base : image.image_base();
    const ModuleInfo module(image, discovery, base);
    const unsigned chunks = std::max(1u, options.chunks);
    const bool write = !out_dir.empty();
    if (write && !valid_identifier(options.name)) {
        throw std::runtime_error("--name must be a C identifier");
    }

    EmitStats stats;
    std::vector<std::string> sources(chunks);
    for (std::string& source : sources) {
        source =
            fmt::format("{}\n#include \"functions.h\"\n\nusing namespace g6::cpu;\n\n", kBanner);
    }
    const size_t per_chunk = (discovery.functions.size() + chunks - 1) / chunks;
    for (size_t i = 0; i < discovery.functions.size(); ++i) {
        FunctionEmitter emitter(module, discovery.functions[i]);
        const std::string code = emitter.emit(stats);
        if (write) {
            sources[per_chunk == 0 ? 0 : i / per_chunk] += code;
        }
    }
    if (!write) {
        return stats;
    }

    std::filesystem::create_directories(out_dir);
    std::string header = fmt::format("{}#pragma once\n\n#include \"g6/cpu/guest.h\"\n\n", kBanner);
    std::string table = fmt::format("{}\n#include \"functions.h\"\n\n"
                                    "static const g6::cpu::FunctionEntry kEntries[] = {{\n",
                                    kBanner);
    for (const DiscoveredFunction& function : discovery.functions) {
        const uint64_t va = base + function.start;
        header += fmt::format("void {}(g6::cpu::GuestContext& ctx);\n", function_name(va));
        table += fmt::format("    {{{:#x}ull, {}}},\n", va, function_name(va));
    }
    table += fmt::format("}};\n\nextern const g6::cpu::ModuleFunctions g6_module_{0};\n"
                         "const g6::cpu::ModuleFunctions g6_module_{0} = {{\"{0}\", {1:#x}ull, "
                         "{2:#x}ull, kEntries, {3}}};\n",
                         options.name, base, image.size_of_image(), discovery.functions.size());
    if (discovery.functions.empty()) {
        throw std::runtime_error("no functions to emit");
    }

    write_if_changed(out_dir / "functions.h", header);
    for (unsigned i = 0; i < chunks; ++i) {
        write_if_changed(out_dir / fmt::format("functions_{}.cpp", i), sources[i]);
    }
    write_if_changed(out_dir / "table.cpp", table);
    LOG_INFO(x64recomp, "wrote {} functions in {} files to {}", discovery.functions.size(),
             chunks + 2, out_dir.string());
    return stats;
}

} // namespace g6::recomp
